### Additional context

I think the solution is to simply [add another `execUpdate` in processCallResponse](https://github.com/vercel/ai/blob/main/packages/ui-utils/src/process-chat-response.ts#L232-L255):

```typescript
      updateToolInvocationPart(value.toolCallId, invocation);

      // invoke the onToolCall callback if it exists. This is blocking.
      // In the future we should make this non-blocking, which
      // requires additional state management for error handling etc.
      if (onToolCall) {
        execUpdate(); // <------- Add an update here

        const result = await onToolCall({ toolCall: value });
        if (result != null) {
          const invocation = {
            state: 'result',
            step,
            ...value,
            result,
          } as const;

          // store the result in the tool invocation
          message.toolInvocations![message.toolInvocations!.length - 1] =
            invocation;

          updateToolInvocationPart(value.toolCallId, invocation);
        }
      }

      execUpdate();
```
